function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'Fancy' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with Fancy() and no arguments.';
  if (operations.length - 1 > 100000) return 'At most 10^5 calls after the constructor.';
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a) || a.length !== 1 || !Number.isInteger(a[0])) return 'Each call takes one whole number.';
    if (['append', 'addAll', 'multAll'].includes(operations[i])) {
      if (a[0] < 1 || a[0] > 100) return 'val, inc and m are between 1 and 100.';
    } else if (operations[i] === 'getIndex') {
      if (a[0] < 0 || a[0] > 100000) return 'idx is between 0 and 10^5.';
    } else {
      return 'Only append, addAll, multAll and getIndex can follow the constructor.';
    }
  }
  return null;
}

