class Fancy {
  constructor() {
    this.MOD = 1000000007n;
    this.values = [];
    this.mul = 1n;
    this.add = 0n;
  }

  power(base, exponent) {
    let result = 1n;
    while (exponent > 0n) {
      if (exponent % 2n === 1n) {
        result = result * base % this.MOD;
      }
      base = base * base % this.MOD;
      exponent /= 2n;
    }
    return result;
  }

  append(val) {
    const inverse = this.power(this.mul, this.MOD - 2n);
    const shifted = (BigInt(val) - this.add + this.MOD) % this.MOD;
    this.values.push(shifted * inverse % this.MOD);
  }

  addAll(inc) {
    this.add = (this.add + BigInt(inc)) % this.MOD;
  }

  multAll(m) {
    this.mul = this.mul * BigInt(m) % this.MOD;
    this.add = this.add * BigInt(m) % this.MOD;
  }

  getIndex(idx) {
    if (idx >= this.values.length) {
      return -1;
    }
    return Number((this.values[idx] * this.mul + this.add) % this.MOD);
  }
}

