class Fancy {
  constructor() {
    this.seq = [];
  }
  append(val) {
    this.seq.push(val);
  }
  addAll(inc) {
    for (let i = 0; i < this.seq.length; i++) this.seq[i] = (this.seq[i] + inc) % 1000000007;
  }
  multAll(m) {
    // Every value stays below 10^9 + 7, so value * 100 fits safely in a double.
    for (let i = 0; i < this.seq.length; i++) this.seq[i] = (this.seq[i] * m) % 1000000007;
  }
  getIndex(idx) {
    return idx < this.seq.length ? this.seq[idx] : -1;
  }
}

