function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const calls = large ? 499 : int(1, 14);
  const pick = () => rand() < 0.15 ? 100 : rand() < 0.15 ? 1 : int(1, 100);
  const operations = ['Fancy'];
  const args = [[]];
  let length = 0;
  for (let i = 0; i < calls; i++) {
    const r = rand();
    if (r < 0.3) {
      operations.push('append');
      args.push([pick()]);
      length++;
    } else if (r < 0.45) {
      operations.push('addAll');
      args.push([pick()]);
    } else if (r < 0.65) {
      operations.push('multAll');
      args.push([pick()]);
    } else {
      operations.push('getIndex');
      const q = rand();
      args.push([q < 0.05 ? 100000 : q < 0.15 ? length + int(0, 2) : length ? int(0, length - 1) : int(0, 2)]);
    }
  }
  return [operations, args];
}
